let data=[],products=[],assets={},page=1;const main=document.querySelector('main');const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const route=p=>'#/page'+p;const storage={};for(const key of ['favorites','compare','basket']){try{storage[key]=JSON.parse(localStorage.getItem('ts-'+key)||'[]')}catch{storage[key]=[]}}const groups=[['laser','Лазерная резка','Лист и труба',/лазерн.*(станок|труборез)|станок.*лазер/i],['bend','Гибка металла','Листогибы и панелегибы',/листогиб|панелегиб|пресс/i],['router','Фрезерные станки','Дерево, камень и пластик',/фрезерн/i],['metal','Обработка металла','Токарные станки и центры',/токарн|обрабатывающ.*центр/i],['weld','Лазерная сварка','Сварка и очистка',/свароч|очистк|лазерная сварка/i],['furniture','Мебельное оборудование','Раскрой, кромка и сверление',/кромко|раскро|сверлил|присадоч/i],['air','Промышленная вентиляция','Фильтрация и вытяжка',/вентиляц|фильтрац|вытяж/i],['parts','Запчасти и расходники','Комплектующие для станков',/источник|raycus|инструмент|патрон|шпиндель|датчик|запчаст|сопло|линз/i]];const find=p=>data.find(r=>r.path===p);const isimage=u=>!u.endsWith('.svg')&&!u.endsWith('.gif');const image=r=>r?.images.find(isimage)||'';const title=r=>r.title.replace(/\s*[»|]\s*(ТОПСТАНКИ|купить).*$/i,'');function belonging(r,g){return g[3].test(r.title+' '+r.categories.join(' '))}function counters(){for(let k of ['compare','favorites','basket'])document.querySelector('#'+({favorites:'fav',compare:'compare',basket:'basket'}[k])+'link b').textContent=storage[k].length}function toggle(k,p){const a=storage[k],i=a.indexOf(p);if(i<0)a.push(p);else a.splice(i,1);localStorage.setItem('ts-'+k,JSON.stringify(a));counters();toast(i<0?'Добавлено: '+({favorites:'избранное',compare:'сравнение',basket:'заявка'}[k]):'Удалено из списка');document.querySelectorAll(`[data-action="${k}"][data-path="${CSS.escape(p)}"]`).forEach(b=>{b.classList.toggle('active',a.includes(p));b.setAttribute('aria-pressed',a.includes(p));if(k==='basket')b.textContent=a.includes(p)?'Убрать из заявки':'Добавить в заявку'});if(['/compare','/favorites','/basket'].includes(location.hash.slice(1)))render()}function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2300)}function action(k,r,label,symbol){const selected=storage[k].includes(r.path);return `<button class="${symbol?'iconbutton':'secondary'} ${selected?'active':''}" data-action="${k}" data-path="${E(r.path)}" aria-label="${E(label)}" title="${E(label)}" aria-pressed="${selected}">${symbol||label}</button>`}function card(r){return `<article class="card"><a class="cardimage" href="${route(r.path)}"><img src="${image(r)}" alt="${E(title(r))}" loading="lazy"></a><div class="cardbody"><div class="tag">${E(r.categories[0]||'Оборудование с ЧПУ')}</div><h3><a href="${route(r.path)}">${E(title(r))}</a></h3><div class="price">${r.price?E(r.price):'<small>Цена по запросу</small>'}</div><div class="actions"><a class="button" href="${route(r.path)}">Подробнее</a>${action('favorites',r,'В избранное','♡')}${action('compare',r,'Сравнить','≋')}</div></div></article>`}function catcards(){return groups.map(g=>{const p=products.find(r=>belonging(r,g));return `<a class="category" href="#/catalog?group=${g[0]}"><div><h3>${g[1]}</h3><small>${g[2]}</small></div>${p?`<img src="${image(p)}" alt="" loading="lazy">`:''}</a>`}).join('')}function news(n=0){let a=data.filter(r=>r.kind==='article'&&!r.path.includes('/category/'));return n?a.slice(0,n):a}function newscard(r){return `<article class="news"><a href="${route(r.path)}">${image(r)?`<img src="${image(r)}" alt="${E(title(r))}" loading="lazy">`:''}<h3>${E(title(r))}</h3><p>Новости и запуск оборудования</p></a></article>`}function home(){const featured=products.filter(r=>/eg-3015-6000|ts-40-2000|ts-1325\/|ts50a-compact\//.test(r.path));const hero=products.find(r=>r.path.includes('eg-3015-6000'))||products.find(r=>/Лазерный станок/.test(r.title));main.innerHTML=`<section class="intro"><div class="introcopy"><div class="eyebrow">ТОПСТАНКИ · С 2011 ГОДА</div><h1>Станки для вашего<br>производства</h1><p>Оборудование для обработки металла, дерева и камня. Подберите станок, изучите характеристики и обсудите комплектацию со специалистом.</p><a class="button" href="#/catalog">Выбрать оборудование</a></div><a class="heroimage" href="${route(hero.path)}"><img src="${image(hero)}" alt="${E(title(hero))}"><span class="herocaption">${E(title(hero))}</span></a></section><div class="proof"><span><b>01</b>Поставка оборудования</span><span><b>02</b>Запуск и обслуживание</span><span><b>03</b>Обучение операторов</span></div><div class="sectionhead"><h2>Какое оборудование вам нужно?</h2><a href="#/catalog">Весь каталог</a></div><section class="categories">${catcards()}</section><div class="sectionhead"><h2>Оборудование в каталоге</h2><a href="#/catalog">Все ${products.length} моделей</a></div><section class="grid">${(featured.length?featured:products.slice(0,4)).map(card).join('')}</section><div class="sectionhead"><h2>Помощь на каждом этапе</h2></div><section class="services"><a class="service" href="#/page/servis/"><span class="number">01 / СЕРВИС</span><h3>Запуск и обслуживание</h3><p>Пусконаладка, обслуживание оборудования и обращения по работе станков.</p></a><a class="service" href="#/page/obuchenie-operatorov-chpu/"><span class="number">02 / ОБУЧЕНИЕ</span><h3>Подготовка операторов</h3><p>Обучение работе с оборудованием и системами ЧПУ.</p></a><a class="service" href="#/page/stanki-chpu-v-trejd-in/"><span class="number">03 / ТРЕЙД-ИН</span><h3>Обновление оборудования</h3><p>Обмен старых станков на новое оборудование для производства.</p></a></section><div class="sectionhead"><h2>Новости и запуски</h2><a href="#/news">Все новости</a></div><section class="newsgrid">${news(3).map(newscard).join('')}</section>`}function catalog(params){let q=params.get('q')||'',g=groups.find(g=>g[0]===params.get('group'));let list=products.filter(r=>(!g||belonging(r,g))&&(!q||(r.title+' '+r.categories.join(' ')).toLowerCase().includes(q.toLowerCase())));let sort=params.get('sort')||'name';list.sort((a,b)=>sort==='name'?title(a).localeCompare(title(b),'ru'):(parseFloat(a.price.replace(/[^\d]/g,''))||Infinity)-(parseFloat(b.price.replace(/[^\d]/g,''))||Infinity));const max=Math.max(1,Math.ceil(list.length/12));page=Math.min(page,max);main.innerHTML=`<div class="crumb"><a href="#/">Главная</a> / Каталог</div><h1>${q?'Результаты поиска':g?g[1]:'Каталог оборудования'}</h1><div class="cataloglayout"><aside class="sidebar"><h3>Категории оборудования</h3><a class="${!g?'selected':''}" href="#/catalog">Все оборудование</a>${groups.map(x=>`<a class="${g===x?'selected':''}" href="#/catalog?group=${x[0]}">${x[1]}</a>`).join('')}<a href="#/categories">Все разделы каталога</a></aside><div><div class="catalogtools"><p>${list.length} моделей${q?' по запросу «'+E(q)+'»':''}</p><select id="sort" aria-label="Сортировка"><option value="name" ${sort==='name'?'selected':''}>По названию</option><option value="price" ${sort==='price'?'selected':''}>По цене</option></select></div>${list.length?`<div class="grid">${list.slice((page-1)*12,page*12).map(card).join('')}</div><div class="pagination"><button data-page="${page-1}" ${page===1?'disabled':''}>Назад</button><span>${page} / ${max}</span><button data-page="${page+1}" ${page===max?'disabled':''}>Далее</button></div>`:'<div class="empty"><h2>Оборудование не найдено</h2><p>Попробуйте название типа станка или модели.</p><a class="button" href="#/catalog">Открыть весь каталог</a></div>'}</div></div>`;document.querySelector('#sort').onchange=e=>{params.set('sort',e.target.value);location.hash='/catalog?'+params}}function cleancontent(html){const div=document.createElement('div');div.innerHTML=html;div.querySelectorAll('script,style,form,object,embed').forEach(x=>x.remove());div.querySelectorAll('*').forEach(x=>{for(const a of [...x.attributes])if(a.name.startsWith('on')||['style','width','height','class'].includes(a.name)||(a.name==='id'&&!a.value.startsWith('ts-')))x.removeAttribute(a.name)});div.querySelectorAll('.ts-bending-calc').forEach(x=>x.setAttribute('data-calculator','bending'));div.querySelectorAll('input,select').forEach(x=>{const l=x.parentElement.querySelector('label');if(l&&x.id)l.htmlFor=x.id});div.querySelectorAll('a').forEach(a=>{try{const u=new URL(a.getAttribute('href'), 'https://topstanki.ru/');if(u.hostname==='topstanki.ru'&&find(u.pathname))a.href=route(u.pathname);else if(u.protocol==='javascript:')a.removeAttribute('href');else if(u.hostname==='topstanki.ru'){a.target='_blank';a.rel='noopener'}}catch{a.removeAttribute('href')}});return div.innerHTML}function detail(r){const ims=r.images.filter(isimage);main.innerHTML=`<div class="crumb"><a href="#/">Главная</a> / <a href="#/catalog">Каталог</a> / ${E(title(r))}</div><section class="detailtop"><div><div class="gallery"><img id="bigimage" src="${image(r)}" alt="${E(title(r))}"></div><div class="thumbs">${ims.map((im,i)=>`<button data-image="${im}" aria-label="Фото ${i+1}"><img src="${im}" alt="" loading="lazy"></button>`).join('')}</div></div><div><div class="eyebrow">${E(r.categories.join(' · ')||'ТОПСТАНКИ')}</div><h1>${E(title(r))}</h1><div class="price">${r.price?E(r.price):'Цена по запросу'}</div><p>Уточните комплектацию, актуальную стоимость и условия поставки у специалиста.</p><div class="detailbuttons"><button class="primary" data-action="basket" data-path="${E(r.path)}">${storage.basket.includes(r.path)?'Убрать из заявки':'Добавить в заявку'}</button>${action('compare',r,'Сравнить')}${action('favorites',r,'В избранное')}</div><p class="detailnote">Цены сохранены в валюте исходного каталога. Стоимость зависит от комплектации.</p><p><a href="tel:88005052009"><b>8 (800) 505-20-09</b></a><br><a href="mailto:info@topstanki.ru">info@topstanki.ru</a></p><a class="secondary" href="${r.url}" target="_blank" rel="noopener">Оригинальная карточка</a></div></section><section class="details"><h2>Описание и характеристики</h2><div class="content">${cleancontent(r.content)}</div></section>`}function article(r){main.innerHTML=`<div class="crumb"><a href="#/">Главная</a> / ${E(title(r))}</div><article class="article"><h1>${E(title(r))}</h1><div class="content">${cleancontent(r.content)}</div></article>`}function listview(k){let list=storage[k].map(find).filter(Boolean);let heading={compare:'Сравнение оборудования',favorites:'Избранное',basket:'Заявка на оборудование'}[k];main.innerHTML=`<div class="crumb"><a href="#/">Главная</a> / ${heading}</div><h1>${heading}</h1>${!list.length?'<div class="empty"><p>Здесь пока нет оборудования.</p><a class="button" href="#/catalog">Перейти в каталог</a></div>':k==='favorites'?`<div class="grid">${list.map(card).join('')}</div>`:k==='basket'?`<p>Выбранные модели для обсуждения со специалистом.</p>${list.map(r=>`<div class="basketitem"><img src="${image(r)}" alt="${E(title(r))}"><div><h3><a href="${route(r.path)}">${E(title(r))}</a></h3>${E(r.price||'Цена по запросу')}</div><button class="secondary" data-action="basket" data-path="${E(r.path)}">Удалить</button></div>`).join('')}<p class="detailnote">Кнопка откроет почтовую программу с перечнем оборудования. Заявка будет отправлена после отправки письма.</p><a class="button" href="mailto:info@topstanki.ru?subject=${encodeURIComponent('Запрос оборудования ТОПСТАНКИ')}&body=${encodeURIComponent('Здравствуйте! Прошу уточнить стоимость и условия поставки:\n\n'+list.map(r=>title(r)+'\n'+r.url).join('\n\n'))}">Запросить предложение</a>`:`<div class="comparetable"><table><tbody><tr>${list.map(r=>`<th><img src="${image(r)}" alt="${E(title(r))}"><h3><a href="${route(r.path)}">${E(title(r))}</a></h3></th>`).join('')}</tr><tr>${list.map(r=>`<td><b>Стоимость</b><br>${E(r.price||'По запросу')}</td>`).join('')}</tr><tr>${list.map(r=>`<td><b>Категория</b><br>${E(r.categories.join(', ')||'Оборудование')}</td>`).join('')}</tr><tr>${list.map(r=>`<td><details><summary>Характеристики и описание</summary><div class="content">${cleancontent(r.content)}</div></details></td>`).join('')}</tr><tr>${list.map(r=>`<td><button class="secondary" data-action="compare" data-path="${E(r.path)}">Убрать из сравнения</button></td>`).join('')}</tr></tbody></table></div>`}`}function render(){const h=(location.hash.slice(1)||'/'),[p,query]=h.split('?');const params=new URLSearchParams(query);document.querySelector('#query').value=params.get('q')||'';if(p==='/')home();else if(p==='/catalog')catalog(params);else if(p.startsWith('/page')){const r=find(p.slice(5));if(r)r.kind==='product'?detail(r):article(r);else main.innerHTML='<div class="empty"><h1>Страница недоступна</h1><a class="button" href="https://topstanki.ru'+E(p.slice(5))+'" target="_blank" rel="noopener">Открыть на исходном сайте</a></div>'}else if(['favorites','compare','basket'].includes(p.slice(1)))listview(p.slice(1));else if(p==='/news')main.innerHTML=`<div class="crumb"><a href="#/">Главная</a> / Новости</div><h1>Новости и запуск оборудования</h1><div class="newsgrid">${news().map(newscard).join('')}</div>`;else if(p==='/pages'||p==='/categories'){let a=data.filter(r=>p==='/categories'?r.kind==='category':r.kind==='page');main.innerHTML=`<h1>${p==='/categories'?'Все разделы каталога':'Информация и услуги'}</h1><div class="pagelist">${a.map(r=>`<a href="${route(r.path)}">${E(title(r))}</a>`).join('')}</div>`}else home();document.title=(main.querySelector('h1')?.textContent||'Каталог')+' — ТОПСТАНКИ';counters();bindCalculator()}document.querySelector('#search').onsubmit=e=>{e.preventDefault();location.hash='/catalog?q='+encodeURIComponent(document.querySelector('#query').value)};document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)toggle(b.dataset.action,b.dataset.path);const im=e.target.closest('[data-image]');if(im)document.querySelector('#bigimage').src=im.dataset.image;const pg=e.target.closest('[data-page]');if(pg){page=Number(pg.dataset.page);render();window.scrollTo(0,0)}});window.addEventListener('hashchange',()=>{page=1;render();window.scrollTo(0,0)});fetch('/data.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{data=d;products=data.filter(r=>r.kind==='product');render()}).catch(()=>{main.innerHTML='<div class="empty"><h1>Не удалось загрузить каталог</h1><p>Обновите страницу или свяжитесь с нами по телефону 8 (800) 505-20-09.</p><button class="primary" onclick="location.reload()">Повторить</button></div>'});

function bindCalculator(){const s=document.getElementById('ts-thickness');if(!s)return;const v=document.getElementById('ts-v-die'),m=document.getElementById('ts-material'),l=document.getElementById('ts-length'),a=document.getElementById('ts-angle');function calc(){const S=+s.value,V=+v.value,L=+l.value,A=+a.value,M=+m.value;if(!(S>0&&V>0&&L>0&&A>0&&A<180)){document.getElementById('ts-res-ton').textContent='Проверьте значения';return}const rad=(180-A)*Math.PI/180,R=V/6,ton=1.42*M*S*S*L/(1000*V),bd=2*Math.tan(rad/2)*(R+S)-rad*(R+.42*S);document.getElementById('ts-res-ton').textContent=ton.toFixed(1)+' т';document.getElementById('ts-res-rad').textContent=R.toFixed(1)+' мм';document.getElementById('ts-res-bd').textContent=bd.toFixed(2)+' мм'}s.oninput=()=>{v.value=Math.max(4,Math.round(+s.value*8));calc()};[v,m,l,a].forEach(x=>x.oninput=calc);document.getElementById('ts-calc-btn').onclick=calc;v.value=Math.max(4,Math.round(+s.value*8));calc()}
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'search_equipment',title:'Поиск оборудования',description:'Открывает результаты поиска в каталоге ТОПСТАНКИ.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.query!=='string'||input.query.length>200)throw new Error('Укажите поисковый запрос до 200 символов');location.hash='/catalog?q='+encodeURIComponent(input.query);render();return{query:input.query,models:products.filter(r=>r.title.toLowerCase().includes(input.query.toLowerCase())).map(r=>({title:title(r),path:r.path,price:r.price})).slice(0,20)}}})).catch(()=>{})}catch{}}
